def bubble_sort(lst):
    n = len(lst)
    for i in range(n):
        for j in range(0, n-i-1):
            if lst[j] > lst[j+1]:
                lst[j], lst[j+1] = lst[j+1], lst[j]
    return lst

if __name__ == "__main__":
    input_list = input()
    input_list = input_list.split()
    input_list = [int(item) for item in input_list]
    sorted_list = bubble_sort(input_list)
    print(*sorted_list)

